mapper.select:
SELECT quantity
FROM product_inventory
WHERE product_id = #{productId}
  AND outlet_id = #{outletId}

mapper.update:
UPDATE stocktake_product
SET actual_count = COALESCE(actual_count, 0) + #{increment},
    scanned = 1
WHERE stocktake_id = #{stocktakeId}
  AND product_id = #{productId}
